diff --git a/http_client_posix.cc b/http_client_posix.cc
index f59722c..1594bb9 100644
--- a/http_client_posix.cc
+++ b/http_client_posix.cc
@@ -211,7 +211,8 @@ BufferedResponse exchange(PosixConnection &connection, PreparedRequest request,
 		BufferedReceiver receiver(limits, policy, request.context());
 		const auto wire = request.wire();
 		connection.write({wire.data(), wire.size()}, deadline);
-		std::array<char, ResponseParser::read_bytes> buffer;
+		// Batch socket reads independently of the bounded parser feed.
+		std::array<char, 16 * 1024> buffer;
 		while (!receiver.done()) {
 			const auto size = connection.read(buffer, deadline);
 			if (!size) { receiver.eof(); break; }
diff --git a/http_client_response.h b/http_client_response.h
index 44bdb91..e36008f 100644
--- a/http_client_response.h
+++ b/http_client_response.h
@@ -29,7 +29,15 @@ class BufferedReceiver {
 			parser_.feed(bytes, budget);
 			if (parser_.head_ready()) parser_.accept_head();
 			const auto body = parser_.body();
-			if (!body.empty()) response_.body.append(body.data(), body.size());
+			if (!body.empty()) {
+				if (response_.body.empty() && parser_.head().content_length) {
+					const auto length = *parser_.head().content_length;
+					if (length > response_.body.max_size())
+						throw Error(ErrorKind::Limit, "HTTP buffered response size");
+					response_.body.reserve(static_cast<std::size_t>(length));
+				}
+				response_.body.append(body.data(), body.size());
+			}
 			parser_.consume_body(body.size());
 			finish();
 		} catch (const allocators::ResourcePressure &) {
